/**
 * The index (`MEMORY.md`) of a scope and the `<memory>` section injected into
 * sessions.
 *
 * The index is generated by code from note front matter — no model ever
 * rewrites it — and is held to a token budget: "always" lines first, then
 * "pointer" lines, each ordered by priority; whatever does not fit is left to
 * memory_search.
 */

import type { Note } from "./notes.ts";

export const GENERATED_MARK = "<!-- generated by pi-dream from notes/ — edit the notes, not this file -->";

/** Rough token estimate that does not undercount Cyrillic. */
export function estimateTokens(text: string): number {
	return Math.ceil(text.length / 3);
}

export function notePriority(n: Note): number {
	let p = Math.min(n.evidence.length, 6) * 10;
	if (n.pinned) p += 1000;
	p += (n.stats.helpful - 4 * n.stats.harmful) * 5;
	if (n.type === "preference" || n.type === "pitfall") p += 5;
	return p;
}

const byPriority = (a: Note, b: Note) =>
	notePriority(b) - notePriority(a) || (b.updated || "").localeCompare(a.updated || "") || a.id.localeCompare(b.id);

export function indexLine(n: Note): string {
	if (n.index === "always") return `- ${n.title} [${n.id}]`;
	return `- ${n.when || "when relevant"} → [${n.id}] ${n.title}`;
}

export interface IndexResult {
	text: string;
	tokens: number;
	included: string[];
	dropped: string[];
}

export function buildIndex(notes: readonly Note[], title: string, budgetTokens: number): IndexResult {
	const active = notes.filter((n) => n.status === "active" && n.id && n.title);
	const always = active.filter((n) => n.index === "always").sort(byPriority);
	const pointer = active.filter((n) => n.index === "pointer").sort(byPriority);
	const head = [GENERATED_MARK, `# ${title}`];
	const included: string[] = [];
	const dropped: string[] = [];
	const sections: Array<{ heading: string; lines: string[] }> = [];
	let used = 0;
	const fill = (heading: string, list: Note[]) => {
		const lines: string[] = [];
		for (const n of list) {
			const line = indexLine(n);
			const cost = estimateTokens(line) + 1;
			if (used + cost + estimateTokens(heading) > budgetTokens) {
				dropped.push(n.id);
				continue;
			}
			used += cost;
			lines.push(line);
			included.push(n.id);
		}
		if (lines.length) {
			used += estimateTokens(heading);
			sections.push({ heading, lines });
		}
	};
	fill("## Always", always);
	fill("## On demand (memory_read <id>)", pointer);
	const body: string[] = [];
	for (const s of sections) body.push("", s.heading, ...s.lines);
	if (dropped.length) body.push("", `(+${dropped.length} more notes over budget: memory_search)`);
	if (!sections.length && !dropped.length) body.push("", "_No active notes yet._");
	const text = `${[...head, ...body].join("\n")}\n`;
	return { text, tokens: estimateTokens(body.join("\n")), included, dropped };
}

/** The injectable part of an index file: everything after the H1, without placeholders. */
export function indexBody(text: string): string {
	const lines = text.split("\n");
	const h1 = lines.findIndex((l) => l.startsWith("# "));
	const rest = (h1 >= 0 ? lines.slice(h1 + 1) : lines).filter((l) => !l.startsWith("<!--") && l.trim() !== "_No active notes yet._");
	return rest.join("\n").trim();
}

/** Note ids referenced in an index body. */
export function indexIds(body: string): string[] {
	return [...new Set([...body.matchAll(/\[(m-[0-9a-f]{6,12})\]/g)].map((m) => m[1]))];
}

export interface InjectionInput {
	memver?: string;
	global?: string;
	project?: { key: string; body: string };
	maxTokens: number;
}

export const PREAMBLE =
	"Notes distilled from this user's past pi sessions by pi-dream. They can be outdated: the user's words and the current state of the code take precedence. Open a note with memory_read <id>; search notes and past sessions with memory_search; use memory_inbox to keep something for the next memory review.";

function capLines(text: string, maxTokens: number): string {
	if (estimateTokens(text) <= maxTokens) return text;
	const out: string[] = [];
	let used = 0;
	for (const line of text.split("\n")) {
		const cost = estimateTokens(line) + 1;
		if (used + cost > maxTokens) break;
		out.push(line);
		used += cost;
	}
	out.push("(…truncated: memory_search for more)");
	return out.join("\n");
}

/** The `<memory>` section text, or undefined when there is nothing to inject. */
export function renderInjection(input: InjectionInput): string | undefined {
	const parts: string[] = [];
	const demote = (body: string) => body.trim().replace(/^## /gm, "### ");
	if (input.global?.trim()) parts.push("## Global (all projects)", demote(input.global));
	if (input.project?.body.trim()) parts.push(`## Project ${input.project.key}`, demote(input.project.body));
	if (!parts.length) return undefined;
	const head = input.memver ? `${PREAMBLE} (memory ${input.memver})` : PREAMBLE;
	return capLines([head, "", ...parts].join("\n"), input.maxTokens);
}
